func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_inst", main != null, "La scena principale deve aprirsi senza errori"):
		return

	check("has_add_emo", has_function(main, "add_emotion"), "dialogue_system.gd deve implementare add_emotion")
	check("has_change_aff", has_function(main, "change_affinity"), "dialogue_system.gd deve implementare change_affinity")

	# Verifica funzioni preesistenti (regression test)
	var hero_name = call_if_exists(main, "get_speaker_name", ["hero"])
	check("existing_speaker", hero_name == "Eldrin", "get_speaker_name('hero') deve continuare a restituire 'Eldrin'")

	# Test change_affinity
	var new_aff: int = call_if_exists(main, "change_affinity", ["mage", 5], -99)
	check("aff_increase", new_aff == 30, "Aumentare l'affinita' di Lyra di 5 deve restituire 30 (25 + 5)")

	var clamped_aff: int = call_if_exists(main, "change_affinity", ["mage", -50], -99)
	check("aff_clamp_zero", clamped_aff == 0, "L'affinita' non puo' essere negativa e deve fermarsi a 0")

	var missing_aff: int = call_if_exists(main, "change_affinity", ["sconosciuto", 10], 0)
	check("aff_missing", missing_aff == -1, "change_affinity su un personaggio inesistente deve restituire -1")

	# Test add_emotion
	var added_emo := call_if_exists(main, "add_emotion", ["mage", "sad", "Sguardo malinconico"]) as bool
	check("emo_added", added_emo == true, "add_emotion con chiave nuova deve restituire true")

	var chars: Dictionary = get_prop(main, "characters", {})
	var mage_emotions: Dictionary = chars.get("mage", {}).get("emotions", {})
	check("emo_stored", mage_emotions.get("sad") == "Sguardo malinconico", "L'emozione 'sad' deve essere memorizzata nel dizionario del personaggio")

	var duplicate_emo := call_if_exists(main, "add_emotion", ["mage", "sad", "Altra descrizione"]) as bool
	check("emo_no_overwrite", duplicate_emo == false, "add_emotion non deve sovrascrivere emozioni esistenti e deve restituire false")

	var invalid_char_emo := call_if_exists(main, "add_emotion", ["sconosciuto", "happy", "Test"]) as bool
	check("emo_invalid_char", invalid_char_emo == false, "add_emotion su personaggio inesistente deve restituire false")

